        { "text", text = "Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point Rupture; the Lookouts on the open third floor from a one-point Eviscerate. |cOXP_ENEMY_Grand Foreman Puzik Gallywix|r waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then Gouge, Evasion, a healing potion and |cOXP_LOOT_Thistle Tea|r; a friend makes it easy. One head per kill. Then pick |cOXP_PICK_Gallywix's Lockbox|r beside him for the cache: it poisons you with the Touch of Zanzil, which weakens your stealth and agility until |cOXP_FRIENDLY_Serge Hinott|r cures it." },
        { "goto", x = 54.7, y = 5.7, zone = "1413" },
        { "complete", obj = 1, quest = 2478, text = "Kill Mutated Venture Co. Drone: 2" },
        { "mob", name = "Mutated Venture Co. Drone" },
        { "goto", x = 54.66, y = 5.68, zone = "1413" },
        { "complete", obj = 3, quest = 2478, text = "Kill Venture Co. Patroller: 2" },
        { "mob", name = "Venture Co. Patroller" },
        { "goto", x = 54.64, y = 5.77, zone = "1413" },
        { "complete", obj = 2, quest = 2478, text = "Kill Venture Co. Lookout: 2" },
        { "mob", name = "Venture Co. Lookout" },
        { "goto", x = 54.75, y = 5.59, zone = "1413" },
        { "complete", obj = 4, quest = 2478, text = "Gallywix's Head: 1 (|cOXP_LOOT_Gallywix's Head|r: |cOXP_ENEMY_Grand Foreman Puzik Gallywix|r (elite))" },
        { "mob", name = "Grand Foreman Puzik Gallywix" },
        { "goto", x = 54.76, y = 5.56, zone = "1413" },
        { "complete", obj = 6, quest = 2478, text = "Cache of Zanzil's Altered Mixture: 1 (|cOXP_LOOT_Cache of Zanzil's Altered Mixture|r: |cOXP_PICK_Gallywix's Lockbox|r)" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-horde",
        { "text", text = "Back to |cOXP_FRIENDLY_Shenthul|r" },
        { "text", text = "Fly back to Orgrimmar (Ratchet or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep |cOXP_LOOT_Silixiz's Tower Key|r afterwards. Before you leave the Cleft, buy |cOXP_LOOT_Dust of Decay|r and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of Instant Poison takes one of each." },
        { "goto", x = 43.05, y = 53.74, zone = "1454" },
        { "turnin", quest = 2478, text = "Turn in Mission: Possible But Not Probable (|cOXP_FRIENDLY_Shenthul|r: |cOXP_LOOT_Recipe: Thistle Tea|r)" },
        { "target", name = "Shenthul" },
        { "goto", x = 43.05, y = 53.74, zone = "1454" },
        { "accept", quest = 2479, text = "Accept Hinott's Assistance" },
        { "target", name = "Shenthul" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-horde",
        { "text", text = "|cOXP_FRIENDLY_Serge Hinott|r" },
        { "text", text = "Take the zeppelin from Orgrimmar to the Undercity and follow the road south through Silverpine Forest into Hillsbrad, to Tarren Mill. |cOXP_FRIENDLY_Serge Hinott|r works in the building next to the flight path, beside |cOXP_FRIENDLY_Apothecary Lydon|r, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from |cOXP_FRIENDLY_Shenthul|r. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make Instant Poison from Rekkul's dust and vials, and use it on your weapon." },
        { "goto", x = 60.14, y = 18.62, zone = "1424" },
        { "fp", name = "Tarren Mill", text = "Get the Tarren Mill flight path" },
        { "target", name = "Zarise" },
        { "goto", x = 61.63, y = 19.19, zone = "1424" },
        { "turnin", quest = 2479, text = "Turn in Hinott's Assistance" },
        { "target", name = "Serge Hinott" },
        { "goto", x = 61.63, y = 19.19, zone = "1424" },
        { "accept", quest = 2480, text = "Accept Hinott's Assistance" },
        { "target", name = "Serge Hinott" },
        { "finish", quest = 2480, text = "Finish Hinott's Assistance: Cure Completed (Wait for the cure)" },
        { "goto", x = 61.63, y = 19.19, zone = "1424" },
        { "turnin", quest = 2480, text = "Turn in Hinott's Assistance (|cOXP_FRIENDLY_Serge Hinott|r: Poisons)" },
        { "target", name = "Serge Hinott" },
        { "goto", x = 61.63, y = 19.19, zone = "1424" },
        { "item", item = 8095, text = "Use Hinott's Oil (|cOXP_LOOT_Hinott's Oil|r: clears the Touch of Zanzil)" },
      },
      { only = "Orc Shaman/Troll Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "Class quest: {quest:63} (Horde)" },
        { "text", text = "|cOXP_FRIENDLY_Searn Firewarder|r" },
        { "text", text = "At 20 |cOXP_FRIENDLY_Searn Firewarder|r in the |cOXP_PICK_Valley of Wisdom|r sends you to |cOXP_FRIENDLY_Islen Waterseer|r in the Barrens. (Swart in Razor Hill gives the same letter: carry either.)" },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 37.96, y = 37.73, zone = "1454" },
        { "accept", optional = true, quest = 1528, text = "Accept Call of Water" },
        { "target", name = "Searn Firewarder" },
      },
      { only = "Tauren Shaman/Skyborne Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Xanis Flameweaver|r" },
        { "text", text = "At 20 |cOXP_FRIENDLY_Xanis Flameweaver|r, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to |cOXP_FRIENDLY_Islen Waterseer|r in the Barrens. (|cOXP_FRIENDLY_Narm Skychaser|r in Bloodhoof Village gives the same letter: carry either.)" },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 25.16, y = 20.51, zone = "1456" },
        { "accept", optional = true, quest = 1529, text = "Accept Call of Water" },
        { "target", name = "Xanis Flameweaver" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Islen Waterseer|r" },
        { "text", text = "|cOXP_FRIENDLY_Islen Waterseer|r is not in Ratchet: take the small coast road south from Ratchet past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far." },
        { "reach", text = "|cOXP_FRIENDLY_Islen Waterseer|r", x = 65.8, y = 43.8, zone = "1413" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde", when = { { "onquest", quests = { 1528 } } },
        { "goto", x = 65.83, y = 43.78, zone = "1413" },
        { "turnin", quest = 1528, text = "Turn in Call of Water (|cOXP_FRIENDLY_Islen Waterseer|r: |cOXP_FRIENDLY_Searn Firewarder|r's letter)" },
