      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Brine|r" },
        { "text", text = "|cOXP_FRIENDLY_Brine|r lives in the southern Barrens, south of Camp Taurajo: her hut sits on a hilltop of Blackthorn Ridge with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way." },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "turnin", quest = 1530, text = "Turn in Call of Water" },
        { "target", name = "Brine" },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "accept", quest = 1535, text = "Accept Call of Water" },
        { "target", name = "Brine" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "The |cOXP_PICK_Quilboar Watering Hole|r" },
        { "text", text = "The muddy pond below |cOXP_FRIENDLY_Brine|r's hut. Step right into the puddle before you use the |cOXP_LOOT_Empty Brown Waterskin|r (too far away and it refuses). Filling it calls a hostile |cOXP_ENEMY_Razormane Pathfinder|r (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards." },
        { "goto", x = 44.3, y = 76.8, zone = "1413" },
        { "complete", obj = 1, quest = 1535, text = "Use |cOXP_LOOT_Empty Brown Waterskin|r (|cOXP_LOOT_Empty Brown Waterskin|r, standing in the puddle)" },
        { "goto", x = 44.28, y = 76.75, zone = "1413" },
        { "complete", obj = 1, quest = 1535, text = "Filled Brown Waterskin: 1" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Brine|r" },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "turnin", quest = 1535, text = "Turn in Call of Water" },
        { "target", name = "Brine" },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "accept", quest = 1536, text = "Accept Call of Water" },
        { "target", name = "Brine" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "The |cOXP_PICK_Spring Well|r" },
        { "text", text = "The |cOXP_PICK_Spring Well|r stands in the middle of Tarren Mill, just outside the church. From the Barrens: the zeppelin from Orgrimmar to Tirisfal Glades, then south past the Undercity and through Silverpine Forest (or fly once you have the Tarren Mill flight path). Hillsbrad is contested: Alliance players may attack. Stand beside the well and use the |cOXP_LOOT_Empty Red Waterskin|r." },
        { "goto", x = 62.2, y = 20.8, zone = "1424" },
        { "complete", obj = 1, quest = 1536, text = "Use |cOXP_LOOT_Empty Red Waterskin|r (|cOXP_LOOT_Empty Red Waterskin|r, beside the well)" },
        { "goto", x = 62.18, y = 20.79, zone = "1424" },
        { "complete", obj = 1, quest = 1536, text = "Filled Red Waterskin: 1" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Brine|r" },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "turnin", quest = 1536, text = "Turn in Call of Water" },
        { "target", name = "Brine" },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "accept", quest = 1534, text = "Accept Call of Water" },
        { "target", name = "Brine" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "The Ruins of Stardust" },
        { "text", text = "The right fountain stands in a ring of standing stones on the island of the small green lake south of Astranaar, west of Lake Mystral (not the island in Lake Mystral itself). From the Barrens take the road north through the Mor'shan Rampart and on west. Water elementals and walking treants guard the lake and root you in place; an elite |cOXP_FRIENDLY_Wandering Protector|r roams Ashenvale and can pass close by. Use the |cOXP_LOOT_Empty Blue Waterskin|r beside the fountain." },
        { "goto", x = 33.6, y = 67.5, zone = "1440" },
        { "complete", obj = 1, quest = 1534, text = "Use |cOXP_LOOT_Empty Blue Waterskin|r (|cOXP_LOOT_Empty Blue Waterskin|r, beside the fountain)" },
        { "goto", x = 33.55, y = 67.47, zone = "1440" },
        { "complete", obj = 1, quest = 1534, text = "Filled Blue Waterskin: 1" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Brine|r" },
        { "text", text = "Back to |cOXP_FRIENDLY_Brine|r. She gives you the |cOXP_LOOT_Vial of Purest Water|r for |cOXP_FRIENDLY_Islen Waterseer|r." },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "turnin", quest = 1534, text = "Turn in Call of Water" },
        { "target", name = "Brine" },
        { "goto", x = 43.42, y = 77.41, zone = "1413" },
        { "accept", quest = 220, text = "Accept Call of Water (the |cOXP_LOOT_Vial of Purest Water|r, for |cOXP_FRIENDLY_Islen Waterseer|r)" },
        { "target", name = "Brine" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Islen Waterseer|r" },
        { "text", text = "|cOXP_FRIENDLY_Islen Waterseer|r hands you the |cOXP_LOOT_Water Sapta|r and the |cOXP_LOOT_Remaining Drops of Purest Water|r: take everything she offers before you leave for Silverpine, or you will be back for more." },
        { "goto", x = 65.83, y = 43.78, zone = "1413" },
        { "turnin", quest = 220, text = "Turn in Call of Water (|cOXP_FRIENDLY_Islen Waterseer|r: your |cOXP_LOOT_Water Sapta|r)" },
        { "target", name = "Islen Waterseer" },
        { "goto", x = 65.83, y = 43.78, zone = "1413" },
        { "accept", quest = 63, text = "Accept Call of Water" },
        { "target", name = "Islen Waterseer" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde", when = { { "onquest", quests = { 63 } }, { "has", item = 6637, n = 1, neg = true } },
        { "text", text = "Lost the Water Sapta?" },
        { "text", text = "Only if the Water Sapta is gone from your bags: |cOXP_FRIENDLY_Islen Waterseer|r gives you another." },
        { "goto", x = 65.83, y = 43.78, zone = "1413" },
        { "turnin", quest = 972, text = "Turn in Water Sapta (|cOXP_FRIENDLY_Islen Waterseer|r: a new Water Sapta)" },
        { "target", name = "Islen Waterseer" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "The |cOXP_PICK_Brazier of Everfount|r" },
        { "text", text = "Fly to the Sepulcher. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the |cOXP_LOOT_Water Sapta|r beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The |cOXP_ENEMY_Corrupt Minor Manifestation of Water|r is level 22 and casts Frost Shock and Frost Nova; if someone just killed it, it is back in about three minutes. Its bracers always drop." },
        { "goto", x = 38.3, y = 44.6, zone = "1421" },
        { "complete", obj = 1, quest = 63, text = "Use |cOXP_LOOT_Water Sapta|r (|cOXP_LOOT_Water Sapta|r, beside the standing stone)" },
        { "goto", x = 38.78, y = 44.26, zone = "1421" },
        { "complete", obj = 1, quest = 63, text = "Corrupt Manifestation's Bracers: 1" },
        { "mob", name = "Corrupt Minor Manifestation of Water" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "The |cOXP_FRIENDLY_Minor Manifestation of Water|r" },
        { "text", text = "Click the |cOXP_PICK_Brazier of Everfount|r to place the bracers and the drops. A few seconds later the pure |cOXP_FRIENDLY_Minor Manifestation of Water|r rises on the stone in the middle of the pool: speak to it while the Sapta Sight lasts (drink again by the stone if it has worn off). It gives you the |cOXP_LOOT_Shard of Water|r for |cOXP_FRIENDLY_Islen Waterseer|r. Gone before you could speak to it? Back at |cOXP_FRIENDLY_Islen Waterseer|r ask for Call of Water (a fresh Water Sapta for |cOXP_FRIENDLY_Tiev Mordune|r, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it." },
        { "goto", x = 38.26, y = 44.56, zone = "1421" },
        { "turnin", quest = 63, text = "Turn in Call of Water" },
        { "goto", x = 38.26, y = 44.56, zone = "1421" },
        { "accept", quest = 100, text = "Accept Call of Water" },
        { "goto", x = 38.65, y = 44.58, zone = "1421" },
        { "turnin", quest = 100, text = "Turn in Call of Water" },
        { "target", name = "Minor Manifestation of Water" },
        { "goto", x = 38.65, y = 44.58, zone = "1421" },
        { "accept", quest = 96, text = "Accept Call of Water" },
        { "target", name = "Minor Manifestation of Water" },
      },
      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-water-horde",
        { "text", text = "|cOXP_FRIENDLY_Islen Waterseer|r" },
        { "text", text = "Back to |cOXP_FRIENDLY_Islen Waterseer|r south of Ratchet. Keep the |cOXP_LOOT_Water Totem|r in your bags for good: every water totem needs it." },
        { "goto", x = 65.83, y = 43.78, zone = "1413" },
        { "turnin", quest = 96, text = "Turn in Call of Water (|cOXP_FRIENDLY_Islen Waterseer|r: Healing Stream Totem and your |cOXP_LOOT_Water Totem|r)" },
        { "target", name = "Islen Waterseer" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "Class quest: Succubus and Incubus (Horde)" },
        { "text", text = "Devourer of Souls (Orgrimmar)" },
        { "text", text = "At 20 |cOXP_FRIENDLY_Gan'rul Bloodeye|r, in the |cOXP_PICK_Cleft of Shadow|r under the |cOXP_PICK_Valley of Strength|r, sends you to |cOXP_FRIENDLY_Cazul|r a few steps away. Two trainers start these demons, |cOXP_FRIENDLY_Gan'rul Bloodeye|r here and |cOXP_FRIENDLY_Carendin Halgar|r in the Undercity, and you can take only one; this guide follows whichever Devourer of Souls you took. |cOXP_FRIENDLY_Cazul|r offers both of Orgrimmar's branches: take both." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 48.25, y = 45.28, zone = "1454" },
        { "accept", quest = 1507, text = "Accept Devourer of Souls" },
        { "target", name = "Gan'rul Bloodeye" },
