        { "target", name = "Cazul" },
        { "goto", x = 47.06, y = 46.43, zone = "1454" },
        { "accept", quest = 1508, text = "Accept Blind Cazul (the succubus)" },
        { "target", name = "Cazul" },
        { "goto", x = 47.06, y = 46.43, zone = "1454" },
        { "accept", quest = 65601, text = "Accept Love Hurts (the incubus)" },
        { "target", name = "Cazul" },
