      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_FRIENDLY_Zankaja|r" },
        { "text", text = "|cOXP_FRIENDLY_Zankaja|r lives in a hut up on the cliffs on the west side of the city, above the |cOXP_PICK_Valley of Strength|r: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads." },
        { "goto", x = 37.04, y = 59.45, zone = "1454" },
        { "turnin", quest = 1508, text = "Turn in Blind Cazul" },
        { "target", name = "Zankaja" },
        { "goto", x = 37.04, y = 59.45, zone = "1454" },
        { "accept", quest = 1509, text = "Accept News of Dogran" },
        { "target", name = "Zankaja" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_FRIENDLY_Magar|r" },
        { "text", text = "|cOXP_FRIENDLY_Magar|r keeps |cOXP_PICK_Magar's Cloth Goods|r on the main street east of the |cOXP_PICK_Cleft of Shadow|r. He asks you to look for his mate Krilge in Ashenvale." },
        { "goto", x = 63.65, y = 49.93, zone = "1454" },
        { "turnin", quest = 65601, text = "Turn in Love Hurts" },
        { "target", name = "Magar" },
