      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_FRIENDLY_Gazrog|r" },
        { "text", text = "|cOXP_FRIENDLY_Gazrog|r waits in front of the inn at the Crossroads. He sends you on to |cOXP_FRIENDLY_Ken'zigla|r at Malaka'jin, in Stonetalon Mountains." },
        { "goto", x = 51.93, y = 30.32, zone = "1413" },
        { "turnin", quest = 1509, text = "Turn in News of Dogran" },
        { "target", name = "Gazrog" },
