      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_FRIENDLY_Ken'zigla|r" },
        { "text", text = "Take the road west from the Crossroads into Stonetalon Mountains and, just past the border, the faint trail up to the left (south): Malaka'jin cannot be reached from the main road. |cOXP_FRIENDLY_Ken'zigla|r hands you her draught for |cOXP_FRIENDLY_Grunt Logmar|r." },
        { "goto", x = 73.25, y = 95.13, zone = "1442" },
        { "turnin", quest = 1510, text = "Turn in News of Dogran (|cOXP_FRIENDLY_Ken'zigla|r, Malaka'jin)" },
        { "target", name = "Ken'zigla" },
        { "goto", x = 73.25, y = 95.13, zone = "1442" },
        { "accept", quest = 1511, text = "Accept Ken'zigla's Draught" },
        { "target", name = "Ken'zigla" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_FRIENDLY_Grunt Dogran|r" },
        { "text", text = "|cOXP_FRIENDLY_Grunt Logmar|r stands at Camp Taurajo, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for |cOXP_FRIENDLY_Gan'rul Bloodeye|r. Keep it." },
        { "goto", x = 44.62, y = 59.27, zone = "1413" },
        { "turnin", quest = 1511, text = "Turn in Ken'zigla's Draught (|cOXP_FRIENDLY_Grunt Logmar|r, Camp Taurajo)" },
        { "target", name = "Grunt Logmar" },
        { "goto", x = 44.62, y = 59.27, zone = "1413" },
        { "accept", quest = 1515, text = "Accept Dogran's Captivity" },
