        { "goto", x = 43.3, y = 47.89, zone = "1413" },
        { "turnin", quest = 1515, text = "Turn in Dogran's Captivity" },
        { "target", name = "Grunt Dogran" },
        { "goto", x = 43.3, y = 47.89, zone = "1413" },
        { "accept", quest = 1512, text = "Accept Love's Gift" },
        { "target", name = "Grunt Dogran" },
