      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "The Binding: succubus (Orgrimmar)" },
        { "text", text = "Back to |cOXP_FRIENDLY_Gan'rul Bloodeye|r with the pendant. He hands you |cOXP_LOOT_Dogran's Pendant|r: take it across the |cOXP_PICK_Cleft of Shadow|r to |cOXP_FRIENDLY_Neeru Fireblade|r's tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: |cOXP_FRIENDLY_Gan'rul Bloodeye|r takes it back." },
        { "goto", x = 48.25, y = 45.28, zone = "1454" },
        { "turnin", quest = 1512, text = "Turn in Love's Gift" },
        { "target", name = "Gan'rul Bloodeye" },
        { "goto", x = 48.25, y = 45.28, zone = "1454" },
        { "accept", quest = 1513, text = "Accept The Binding" },
