        { "goto", x = 49.4, y = 50, zone = "1454" },
        { "item", item = 6626, text = "Use Dogran's Pendant (|cOXP_LOOT_Dogran's Pendant|r, on the circle in Neeru's tent)" },
        { "goto", x = 49.4, y = 50, zone = "1454" },
