        { "target", name = "Gan'rul Bloodeye" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde", when = { { "onquest", quests = { 65610 } } },
        { "text", text = "Fallen Sky Lake" },
        { "text", text = "Fallen Sky Lake lies in southern Ashenvale, south-west of Splintertree Post. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the |cOXP_LOOT_Withered Scarf|r about one time in twenty, and the lone |cOXP_ENEMY_Shadethicket Oracle|r (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in Ashenvale. They respawn in five minutes." },
        { "xp", level = 24, text = "Reach level 24" },
        { "goto", x = 72.4, y = 68.06, zone = "1440" },
        { "complete", obj = 1, quest = 65610, text = "Withered Scarf: 1" },
        { "mob", name = "Shadethicket Stone Mover" },
        { "mob", name = "Shadethicket Bark Ripper" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "The Binding: incubus (Orgrimmar)" },
        { "text", text = "Back to |cOXP_FRIENDLY_Gan'rul Bloodeye|r with the scarf, then use the |cOXP_LOOT_Withered Scarf|r on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: |cOXP_FRIENDLY_Gan'rul Bloodeye|r takes it back." },
        { "goto", x = 48.25, y = 45.28, zone = "1454" },
        { "turnin", quest = 65610, text = "Turn in Wish You Were Here" },
