      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "Devourer of Souls (Undercity)" },
        { "text", text = "|cOXP_PICK_The Undercity|r's version, for warlocks who took |cOXP_FRIENDLY_Carendin Halgar|r's Devourer of Souls instead of |cOXP_FRIENDLY_Gan'rul Bloodeye|r's. At 20 |cOXP_FRIENDLY_Carendin Halgar|r, in the |cOXP_PICK_Magic Quarter|r, sends you to |cOXP_FRIENDLY_Godrick Farsan|r close by. |cOXP_FRIENDLY_Godrick Farsan|r shows you an image of each quarry and offers both branches: take both." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 85.06, y = 25.99, zone = "1458" },
        { "accept", quest = 1472, text = "Accept Devourer of Souls" },
        { "target", name = "Carendin Halgar" },
