        { "target", name = "Godrick Farsan" },
        { "goto", x = 84.81, y = 14.83, zone = "1458" },
        { "accept", quest = 1476, text = "Accept Hearts of the Pure (the succubus)" },
        { "target", name = "Godrick Farsan" },
        { "goto", x = 84.81, y = 14.83, zone = "1458" },
