        { "target", name = "Godrick Farsan" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "Silverpine hearts" },
        { "text", text = "|cOXP_ENEMY_Avelina Lilly|r (level 22) works as a tailor for the Dalaran wizards at Ambermill, in eastern Silverpine: the wizards around her are hostile. |cOXP_ENEMY_Dalin Forgewright|r (level 20, not elite) patrols near the Greymane Wall in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart." },
        { "goto", x = 63.12, y = 65.27, zone = "1421" },
        { "complete", obj = 1, quest = 65593, text = "Avelina's Heart: 1" },
        { "mob", name = "Avelina Lilly" },
        { "goto", x = 47.6, y = 85.65, zone = "1421" },
        { "complete", obj = 1, quest = 1476, text = "Dalin's Heart: 1" },
        { "mob", name = "Dalin Forgewright" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_ENEMY_Corma Villard|r" },
        { "text", text = "|cOXP_ENEMY_Corma Villard|r (level 22, not elite; Comar in older records) wanders the north of the Wetlands just past the Thandol Span, to the right as you come off the bridge. From the Undercity head through Hillsbrad and Arathi Highlands, where the mobs are 30 and up. Attacking her flags you for PvP." },
        { "goto", x = 49.93, y = 12.55, zone = "1437" },
        { "complete", obj = 2, quest = 1476, text = "Corma's Heart: 1" },
        { "mob", name = "Corma Villard" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "The Binding: succubus (Undercity)" },
        { "text", text = "Back to |cOXP_FRIENDLY_Carendin Halgar|r with Dalin's and |cOXP_ENEMY_Corma Villard|r's hearts. He hands you the |cOXP_LOOT_Pure Hearts|r: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, |cOXP_FRIENDLY_Carendin Halgar|r takes them back." },
        { "goto", x = 85.06, y = 25.99, zone = "1458" },
        { "turnin", quest = 1476, text = "Turn in Hearts of the Pure" },
        { "target", name = "Carendin Halgar" },
