      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "|cOXP_ENEMY_Isaac Pearson|r" },
        { "text", text = "|cOXP_ENEMY_Isaac Pearson|r (level 22) works in Ratchet, on the Barrens coast, at one of two spots in town: take the zeppelin to Durotar and head south, or fly from Orgrimmar. He is an Alliance-friendly human: attacking him can flag you for PvP." },
        { "goto", x = 62.13, y = 38.35, zone = "1413" },
        { "complete", obj = 2, quest = 65593, text = "Isaac's Heart: 1" },
        { "mob", name = "Isaac Pearson" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-horde",
        { "text", text = "The Binding: incubus (Undercity)" },
        { "text", text = "Back to |cOXP_FRIENDLY_Carendin Halgar|r with the lovers' hearts, then place the |cOXP_LOOT_Lovers' Hearts|r on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: |cOXP_FRIENDLY_Carendin Halgar|r takes them back." },
        { "goto", x = 85.06, y = 25.99, zone = "1458" },
        { "turnin", quest = 65593, text = "Turn in Hearts of the Lovers" },
