      { only = "Orc Warrior/Troll Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Class quest: {quest:1838}" },
        { "text", text = "Speak with Ruga (Orgrimmar)" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Sorek|r in the |cOXP_PICK_Valley of Honor|r sends you to |cOXP_FRIENDLY_Ruga Ragetotem|r in Camp Taurajo." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 80.39, y = 32.38, zone = "1454" },
        { "accept", quest = 1823, text = "Accept Speak with Ruga" },
        { "target", name = "Sorek" },
      },
      { only = "Tauren Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Speak with Ruga (Thunder Bluff)" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Torm Ragetotem|r, the warrior trainer of Thunder Bluff, sends you to |cOXP_FRIENDLY_Ruga Ragetotem|r in Camp Taurajo." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 57.24, y = 87.37, zone = "1456" },
        { "accept", quest = 1823, text = "Accept Speak with Ruga" },
        { "target", name = "Torm Ragetotem" },
      },
      { only = "Scourge Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Speak with Ruga (Undercity)" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Baltus Fowler|r, a warrior trainer of the Undercity, sends you to |cOXP_FRIENDLY_Ruga Ragetotem|r in Camp Taurajo." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 47.4, y = 17.29, zone = "1458" },
        { "accept", quest = 1823, text = "Accept Speak with Ruga" },
        { "target", name = "Baltus Fowler" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "|cOXP_FRIENDLY_Ruga Ragetotem|r" },
        { "text", text = "Fly to Camp Taurajo. |cOXP_FRIENDLY_Ruga Ragetotem|r stands in the hut with the leatherworking and tailoring trainers." },
        { "goto", x = 44.67, y = 59.42, zone = "1413" },
        { "turnin", quest = 1823, text = "Turn in Speak with Ruga" },
        { "target", name = "Ruga Ragetotem" },
        { "goto", x = 44.67, y = 59.42, zone = "1413" },
        { "accept", quest = 1824, text = "Accept Trial at the Field of Giants" },
        { "target", name = "Ruga Ragetotem" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Trial at the Field of Giants" },
        { "text", text = "You have 30 minutes, and each |cOXP_LOOT_Twitching Antenna|r rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the Field of Giants south of Camp Taurajo; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. |cOXP_LOOT_Ruga's Bulwark|r, a shield, is the reward." },
        { "goto", x = 45.11, y = 68.95, zone = "1413" },
        { "complete", obj = 1, quest = 1824, text = "Twitching Antenna: 5 (|cOXP_LOOT_Twitching Antenna|r, from the silithid)" },
        { "mob", name = "Silithid Swarmer" },
        { "mob", name = "Silithid Creeper" },
        { "mob", name = "Silithid Grub" },
        { "goto", x = 44.67, y = 59.42, zone = "1413" },
        { "turnin", quest = 1824, text = "Turn in Trial at the Field of Giants (|cOXP_FRIENDLY_Ruga Ragetotem|r: |cOXP_LOOT_Ruga's Bulwark|r)" },
        { "target", name = "Ruga Ragetotem" },
        { "goto", x = 44.67, y = 59.42, zone = "1413" },
        { "accept", quest = 1825, text = "Accept Speak with Thun'grim" },
        { "target", name = "Ruga Ragetotem" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "|cOXP_FRIENDLY_Thun'grim Firegaze|r" },
        { "text", text = "|cOXP_FRIENDLY_Thun'grim Firegaze|r's hut sits on top of Thorn Hill, east of the Crossroads: climb the broad ridge on the north or east side. Brutal Armor is a level 30 quest; take it now and gather on the way. |cOXP_LOOT_Thun'grim's Instructions|r list where each material comes from." },
        { "goto", x = 57.23, y = 30.34, zone = "1413" },
        { "turnin", quest = 1825, text = "Turn in Speak with Thun'grim" },
        { "target", name = "Thun'grim Firegaze" },
        { "goto", x = 57.23, y = 30.34, zone = "1413" },
        { "accept", quest = 1838, text = "Accept Brutal Armor" },
        { "target", name = "Thun'grim Firegaze" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Windshear Mine" },
        { "text", text = "You need 15 Smoky Iron Ingots. The Windshear Mine lies at the east end of Windshear Crag, east of Sun Rock Retreat; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast Frostbolt." },
        { "goto", x = 71.76, y = 60.29, zone = "1442" },
        { "complete", obj = 1, quest = 1838, text = "Smoky Iron Ingot: 15 (|cOXP_LOOT_Smoky Iron Ingot|r, from the Windshear kobolds)" },
        { "mob", name = "Windshear Vermin" },
        { "mob", name = "Windshear Digger" },
        { "mob", name = "Windshear Tunnel Rat" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Hillsbrad Miners" },
        { "text", text = "You need 10 |cOXP_LOOT_Powdered Azurite|r. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of Southshore and drop the azurite four kills in five; they fight in Defensive Stance, sunder your armor and run for help at 30% health. Fly to Tarren Mill and head south-west." },
        { "xp", level = 25, text = "Reach level 25" },
        { "goto", x = 30, y = 54.97, zone = "1424" },
        { "complete", obj = 2, quest = 1838, text = "Powdered Azurite: 10 (|cOXP_LOOT_Powdered Azurite|r, from the Hillsbrad Miners)" },
        { "mob", name = "Hillsbrad Miner" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Roogug in Razorfen Kraul" },
        { "text", text = "Roogug is an elite quilboar (level 28) inside Razorfen Kraul, the dungeon at the south end of the Barrens; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts Lightning Bolt and calls Earth Rumblers. The vial always drops." },
        { "xp", level = 26, text = "Reach level 26" },
        { "goto", x = 42.9, y = 90.2, zone = "1413" },
        { "complete", obj = 4, quest = 1838, text = "Vial of Phlogiston: 1 (|cOXP_LOOT_Vial of Phlogiston|r, from Roogug)" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Iron Bars" },
        { "text", text = "You need 10 Iron Bars. Miners smelt them from |cOXP_LOOT_Iron Ore|r (one ore a bar, Smelt Iron at Mining 125); everyone else buys them at the auction house in Orgrimmar." },
        { "goto", x = 55.9, y = 62.7, zone = "1454" },
        { "complete", obj = 3, quest = 1838, text = "Iron Bar: 10 (Iron Bars: |cOXP_FRIENDLY_Auctioneer Thathung|r)" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "Brutal Hauberk" },
        { "text", text = "Back to |cOXP_FRIENDLY_Thun'grim Firegaze|r on Thorn Hill. Brutal Hauberk is the first piece; he then sends you to three crafters, one per piece: take all three." },
        { "goto", x = 57.23, y = 30.34, zone = "1413" },
