      { only = "Warrior", source = "polestar:forever/class/warrior/brutal-armor",
        { "text", text = "|cOXP_FRIENDLY_Velora Nitely|r" },
        { "text", text = "Take the zeppelin from Orgrimmar to Tirisfal Glades; |cOXP_FRIENDLY_Velora Nitely|r works in the Undercity's |cOXP_PICK_Trade Quarter|r. She wants 8 Sturdy Dragonmaw Shinbones." },
