      { only = "Rogue", source = "polestar:forever/class/rogue/ravenholdt",
        { "text", text = "Class quest: {npc:13936}" },
        { "text", text = "The |cOXP_LOOT_Elegant Letter|r" },
        { "text", text = "At 24 any capital's rogue trainer (|cOXP_FRIENDLY_Master Mathias Shaw|r or |cOXP_FRIENDLY_Osborne the Night Man|r in Stormwind, Gest or Ormok in Orgrimmar, and the others) has an |cOXP_LOOT_Elegant Letter|r from |cOXP_ENEMY_Ravenholdt|r for you: ask for it in their talk window. Open it: the quest gives you the |cOXP_LOOT_Seal of Ravenholdt|r for |cOXP_FRIENDLY_Fahrad|r. Learn Detect Traps from your trainer first if you have not; the way in is a test of it." },
        { "xp", level = 24, text = "Reach level 24" },
        { "accept", quest = 6681, text = "Accept The Manor, Ravenholdt" },
        { "item", item = 17126, text = "Starts from |cOXP_LOOT_Elegant Letter|r" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/ravenholdt",
        { "text", text = "Ravenholdt Manor" },
        { "text", text = "Horde fly to Tarren Mill, Alliance to Southshore. The trail to the manor is hard to see: it starts behind the plateau north of Durnholde Keep, east of Tarren Mill, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast Detect Traps near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies Ravenholdt Manor: |cOXP_FRIENDLY_Fahrad|r is upstairs inside. Do not attack anyone at the manor: it costs |cOXP_ENEMY_Ravenholdt|r reputation." },
        { "goto", x = 78.64, y = 17.84, zone = "1424" },
        { "complete", obj = 1, quest = 6681, text = "Kill Ravenholdt: 1 (Rite of Cunning: Detect Traps beside the tunnel chest)" },
        { "mob", name = "Ravenholdt" },
        { "goto", x = 84.45, y = 80.32, zone = "1416" },
        { "turnin", quest = 6681, text = "Turn in The Manor, Ravenholdt" },
        { "target", name = "Fahrad" },
        { "goto", x = 84.93, y = 80.38, zone = "1416" },
        { "accept", quest = 96779, text = "Accept Syndicate Sabotage" },
        { "target", name = "Myrokos Silentform" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/ravenholdt",
        { "text", text = "|cOXP_ENEMY_Lord Tomas|r" },
        { "text", text = "|cOXP_ENEMY_Lord Tomas|r is inside Durnholde Keep, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says |cOXP_FRIENDLY_Myrokos Silentform|r. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry Syndicate Emblems for the guards' repeatable reputation quest." },
        { "goto", x = 79.35, y = 46.02, zone = "1424" },
        { "complete", obj = 1, quest = 96779, text = "Kill Lord Tomas: 1" },
